const fs = require("fs");
const path = require("path");

const ROOT = process.cwd();

const FILES = {
  fixer:
    "scripts/fix-forward-oos-v1-path-import.cjs",

  verify:
    "scripts/forward-oos-v1-path-import-static-verify.cjs"
};

const payloads = {
  [FILES.fixer]:
    "",

  [FILES.verify]:
    ""
};

for (const [rel, encoded] of Object.entries(payloads)) {
  const target =
    path.join(
      ROOT,
      rel
    );

  fs.mkdirSync(
    path.dirname(target),
    {
      recursive: true
    }
  );

  fs.writeFileSync(
    target,
    Buffer.from(
      encoded,
      "base64"
    ).toString("utf8"),
    "utf8"
  );
}

console.log(
  JSON.stringify(
    {
      status:
        "AI_STOCK_LAB_FORWARD_OOS_V1_PATH_IMPORT_REPAIR_TOOLING_INSTALLED",

      generatedFiles:
        Object.values(FILES),

      repairTarget:
        "scripts/true-forward-oos-first-session-orchestrator-v1.ts",

      expectedRepair:
        "import path from \"node:path\";",

      safety: {
        sourceOnly:
          true,
        databaseReads:
          0,
        databaseWrites:
          0,
        producerExecuted:
          false,
        ordersCreated:
          0,
        positionsChanged:
          0,
        realTradingEnabled:
          false
      },

      nextAction:
        "RUN_REPAIR_STATIC_AND_CLEAN_TSC"
    },
    null,
    2
  )
);

process.exitCode = 0;
